// generated by build-games: content/games/<slug>.html -> bu fayl. Əl ilə dəyişmə; node scripts/build-games.mjs işlət.
export default "<!doctype html>\n<html lang=\"az\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<title>Kərpic qırma</title>\n<style>\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{margin:0;min-height:100%;background:radial-gradient(circle at 50% 0,#17224a,#070b18 70%);color:#e8f0ff;font-family:system-ui,\"Segoe UI\",Roboto,Arial,sans-serif;-webkit-user-select:none;user-select:none}\nbody{display:flex;justify-content:center;padding:10px}\n.wrap{width:100%;max-width:460px;text-align:center}\nh1{margin:6px 0 8px;font-size:24px;letter-spacing:.5px}\n.hud{display:flex;justify-content:space-between;gap:8px;margin:6px 0;font-size:15px}\n.hud span{flex:1;background:#ffffff12;border:1px solid #ffffff22;border-radius:10px;padding:6px 8px}\ncanvas{display:block;margin:0 auto;width:100%;height:auto;border-radius:14px;border:2px solid #4cc9f0;background:#0a1128;touch-action:none;box-shadow:0 0 24px #4cc9f044}\nbutton{font:inherit;color:#fff;background:linear-gradient(#3a86ff,#2563eb);border:0;border-radius:12px;padding:10px 16px;cursor:pointer;box-shadow:0 3px 0 #1b3f9a}\nbutton:active{transform:translateY(2px);box-shadow:none}\n.row{display:flex;gap:8px;justify-content:center;margin:10px 0;flex-wrap:wrap}\n.hint{opacity:.7;font-size:13px;margin:6px 0}\n.msg{min-height:24px;font-weight:700;color:#ffd166;margin:6px 0}\ncanvas{max-width:380px;cursor:none}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<h1>🧱 Kərpic qırma</h1>\n<div class=\"hud\"><span>Xal: <b id=\"sc\">0</b></span><span>Səviyyə: <b id=\"lv\">1</b></span><span>Can: <b id=\"lf\">3</b></span></div>\n<canvas id=\"c\" width=\"360\" height=\"480\"></canvas>\n<div class=\"row\"><button id=\"re\">Yenidən başla</button></div>\n<p class=\"hint\">Barmaqla / siçanla sürüşdür və ya ← → düymələri. Topu buraxmaq üçün toxun.</p>\n</div>\n<script>\nconst W = 360, H = 480, COLS = 8, BW = 38, BH = 16, GAP = 5, OX = 15, OY = 50;\nconst COLORS = ['#ff6b6b', '#ff9f43', '#ffd166', '#7ae582', '#4cc9f0', '#a78bfa', '#f472b6', '#94a3b8'];\nconst cv = document.getElementById('c'), ctx = cv.getContext('2d');\nconst $ = id => document.getElementById(id);\nlet pad, ball, bricks, score, level, lives, state, keys = {}, acc = 0, last = 0;\n\nfunction build() {\n  bricks = []; const rows = Math.min(8, 3 + level);\n  for (let r = 0; r < rows; r++) for (let c = 0; c < COLS; c++)\n    bricks.push({ x: OX + c * (BW + GAP), y: OY + r * (BH + GAP), color: COLORS[r % COLORS.length], alive: true });\n}\nfunction stick() { ball = { x: pad.x + pad.w / 2, y: H - 40, vx: 0, vy: 0, r: 7 }; state = 'ready'; }\nfunction reset() {\n  pad = { x: W / 2 - 38, y: H - 30, w: 76, h: 12 }; score = 0; level = 1; lives = 3; build(); stick(); hud();\n}\nfunction hud() { $('sc').textContent = score; $('lv').textContent = level; $('lf').textContent = lives; }\nfunction launch() {\n  if (state === 'ready') { const sp = 5 + level * 0.4; ball.vx = (Math.random() < 0.5 ? -1 : 1) * sp * 0.5; ball.vy = -sp * 0.87; state = 'play'; }\n  else if (state === 'over') reset();\n}\nfunction update() {\n  if (keys.ArrowLeft || keys.a) pad.x -= 6;\n  if (keys.ArrowRight || keys.d) pad.x += 6;\n  pad.x = Math.max(0, Math.min(W - pad.w, pad.x));\n  if (state === 'ready') { ball.x = pad.x + pad.w / 2; return; }\n  if (state !== 'play') return;\n  ball.x += ball.vx; ball.y += ball.vy;\n  if (ball.x < ball.r) { ball.x = ball.r; ball.vx = Math.abs(ball.vx); }\n  if (ball.x > W - ball.r) { ball.x = W - ball.r; ball.vx = -Math.abs(ball.vx); }\n  if (ball.y < ball.r) { ball.y = ball.r; ball.vy = Math.abs(ball.vy); }\n  if (ball.vy > 0 && ball.y + ball.r >= pad.y && ball.y - ball.r <= pad.y + pad.h && ball.x >= pad.x - 4 && ball.x <= pad.x + pad.w + 4) {\n    const rel = (ball.x - (pad.x + pad.w / 2)) / (pad.w / 2), sp = Math.hypot(ball.vx, ball.vy);\n    ball.vx = sp * rel * 0.8; ball.vy = -Math.sqrt(Math.max(sp * sp - ball.vx * ball.vx, 4)); ball.y = pad.y - ball.r;\n  }\n  for (const b of bricks) {\n    if (!b.alive) continue;\n    const nx = Math.max(b.x, Math.min(ball.x, b.x + BW)), ny = Math.max(b.y, Math.min(ball.y, b.y + BH));\n    const dx = ball.x - nx, dy = ball.y - ny;\n    if (dx * dx + dy * dy > ball.r * ball.r) continue;\n    b.alive = false; score += 10; hud();\n    if (Math.abs(dx) > Math.abs(dy)) ball.vx = dx > 0 ? Math.abs(ball.vx) : -Math.abs(ball.vx);\n    else ball.vy = dy > 0 ? Math.abs(ball.vy) : -Math.abs(ball.vy);\n    break;\n  }\n  if (!bricks.some(b => b.alive)) { level++; score += 50; build(); stick(); hud(); return; }\n  if (ball.y > H + 20) { lives--; hud(); if (lives <= 0) state = 'over'; else stick(); }\n}\nfunction draw() {\n  ctx.fillStyle = '#0a1128'; ctx.fillRect(0, 0, W, H);\n  for (const b of bricks) if (b.alive) {\n    ctx.fillStyle = b.color; ctx.fillRect(b.x, b.y, BW, BH);\n    ctx.fillStyle = '#ffffff44'; ctx.fillRect(b.x, b.y, BW, 4);\n  }\n  ctx.fillStyle = '#4cc9f0'; ctx.beginPath(); (ctx.roundRect || ctx.rect).call(ctx, pad.x, pad.y, pad.w, pad.h, 6); ctx.fill();\n  ctx.fillStyle = '#fff'; ctx.shadowColor = '#fff'; ctx.shadowBlur = 10;\n  ctx.beginPath(); ctx.arc(ball.x, ball.y, ball.r, 0, 7); ctx.fill(); ctx.shadowBlur = 0;\n  ctx.textAlign = 'center'; ctx.font = 'bold 20px system-ui';\n  if (state === 'ready') { ctx.fillStyle = '#fff'; ctx.fillText('Buraxmaq üçün toxun', W / 2, H / 2 + 60); }\n  if (state === 'over') {\n    ctx.fillStyle = '#000b'; ctx.fillRect(0, 170, W, 130); ctx.fillStyle = '#ffd166'; ctx.font = 'bold 30px system-ui';\n    ctx.fillText('Oyun bitdi', W / 2, 220); ctx.fillStyle = '#fff'; ctx.font = '20px system-ui';\n    ctx.fillText('Xal: ' + score + ' — yenidən başlamaq üçün toxun', W / 2, 255);\n  }\n}\nfunction loop(t) {\n  acc += Math.min(100, t - last); last = t;\n  while (acc >= 1000 / 60) { update(); acc -= 1000 / 60; }\n  draw(); requestAnimationFrame(loop);\n}\nfunction moveTo(e) { const r = cv.getBoundingClientRect(); pad.x = Math.max(0, Math.min(W - pad.w, (e.clientX - r.left) * (W / r.width) - pad.w / 2)); }\ncv.addEventListener('pointermove', moveTo);\ncv.addEventListener('pointerdown', e => { e.preventDefault(); moveTo(e); launch(); });\naddEventListener('keydown', e => {\n  keys[e.key] = true;\n  if (['ArrowLeft', 'ArrowRight', ' '].includes(e.key)) e.preventDefault();\n  if (e.key === ' ') launch();\n});\naddEventListener('keyup', e => { keys[e.key] = false; });\n$('re').onclick = reset;\nreset(); requestAnimationFrame(t => { last = t; loop(t); });\n\n</script>\n</body>\n</html>\n";
